      if (f) { var a = el("a", "btn solid", "Read " + (f.length > 1 ? "Part 1" : "PDF")); a.href = f[0][1]; a.target = "_blank"; a.rel = "noopener"; wrap.appendChild(a); }
      wrap.appendChild(link("Show in catalog", function () { goBook(id); }));
